module fsm(
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

    // Define the states
    parameter s0 = 3'b000, s1 = 3'b001, s2 = 3'b010, s3 = 3'b011, s4 = 3'b100, s5 = 3'b101;

    // Current state register
    reg [2:0] ST_cr;

    // Next state logic
    reg [2:0] ST_nt;
    always @(*) begin
        case (ST_cr)
            s0: begin
                if (IN == 1'b0)
                    ST_nt = s1;
                else
                    ST_nt = s0;
            end
            s1: begin
                if (IN == 1'b0)
                    ST_nt = s2;
                else
                    ST_nt = s0;
            end
            s2: begin
                if (IN == 1'b0)
                    ST_nt = s3;
                else
                    ST_nt = s0;
            end
            s3: begin
                if (IN == 1'b0)
                    ST_nt = s0;
                else
                    ST_nt = s4;
            end
            s4: begin
                if (IN == 1'b0)
                    ST_nt = s2;
                else
                    ST_nt = s5;
            end
            s5: begin
                if (IN == 1'b0)
                    ST_nt = s2;
                else
                    ST_nt = s1;
            end
            default: begin
                ST_nt = s0;
            end
        endcase
    end

    // State register update
    always @(posedge CLK or posedge RST) begin
        if (RST)
            ST_cr <= s0;
        else
            ST_cr <= ST_nt;
    end

    // Output logic
    always @(*) begin
        if (RST)
            MATCH = 1'b0;
        else if (ST_cr == s4 && IN == 1'b1)
            MATCH = 1'b1;
        else
            MATCH = 1'b0;
    end

endmodule
